  moneyFlows: {
    cod:{label:"Cash on Delivery",steps:["Customer approves the final revision and confirms COD","Wasla may give rider cash for merchants who require cash","Rider pays exact merchant amount—or pays nothing if already transferred","Rider collects exact customer payable plus any separately accepted redelivery fee","Rider reports each movement; Admin records it","At least daily: starting cash + COD − merchant cash paid = expected cash returned"]},
    transfer:{label:"Customer transfer",steps:["Customer transfers final payable to Wasla's official account","Customer sends receipt; receipt alone is not confirmation","Admin verifies real bank credit, amount, match and duplicate reference","Wasla pays the exact merchant amount by transfer or rider cash according to merchant method","Rider delivers as prepaid; no customer COD collection","Merchant payout and rider cash remain separately recorded"]}
  },
  timers: [
    {title:"WhatsApp confirmation",start:"Website order creation",marks:["1 operating hour: Admin sends CUS-06 recovery","3 total operating hours: Admin checks inbox by Order ID + phone, then may record cancellation"],note:"The system never infers receipt or cancels automatically."},
    {title:"Store response",start:"Admin-declared STO-01 sent time",marks:["1 hour: first reminder","3 hours: second reminder or call","5 hours: final reminder / another channel","7 operating hours: escalation and final Admin check; normal outcome is recorded cancellation if still no response"],note:"Copy/Open does not start the clock. Operating time pauses outside 10:00–22:00."},
    {title:"Customer payment choice",start:"Admin-declared final CUS-03 sent time",marks:["1 hour: first reminder","2 hours: second reminder","3 hours: final reminder","4 operating hours: final bank/conversation checks, then Admin records the approved outcome"],note:"A timely receipt awaiting bank credit stays in payment verification; it is not auto-cancelled."},
    {title:"Preparation & delivery",start:"No approved SLA",marks:["Preparation estimate is informational","16:00 is a normal planning time—not a cutoff","After 22:00 an active order continues only by deliberate Admin coordination"],note:"No rider acceptance timer, delivery SLA, fixed customer wait or automatic clock-based state change."}
  ],
  exceptions: [
    {area:"confirmation",title:"Wrong phone number",what:"No CUS-01 arrived and recovery confirms the registered number is wrong.",admin:"Record Wrong Phone Number cancellation. Old order is never repaired or transferred.",result:"cancelled"},
    {area:"confirmation",title:"Customer never sends WhatsApp",what:"Three operating hours pass without matched CUS-01 or response.",admin:"Search inbox by Order ID and phone, attest the check, then record No Customer Confirmation.",result:"cancelled"},
    {area:"store",title:"Store does not respond",what:"Seven operating hours pass from declared STO-01 send after reminders.",admin:"Perform final inbox/search/call check and normally record Store No Response if no reply exists.",result:"cancelled"},
    {area:"store",title:"Product unavailable",what:"Store cannot supply one or more listed items.",admin:"Discuss remove/replace/cancel, create an immutable revision and obtain exact customer approval. Same-store listed replacements return to store confirmation.",result:"awaiting_customer_decision / awaiting_store_confirmation"},
    {area:"store",title:"Price changes before payment",what:"Store confirms a current merchant price different from the order snapshot.",admin:"Recalculate using policy, show old → new values and obtain customer approval before payment.",result:"awaiting_customer_decision"},
    {area:"store",title:"Price changes after confirmed payment",what:"Merchant attempts to increase a price it already confirmed.",admin:"Do not charge customer more. Record merchant issue and handle exceptional dispute with cofounders.",result:"No automatic state change"},
    {area:"payment",title:"No payment choice",what:"No receipt or explicit COD response by four operating hours.",admin:"Check bank/payment channel/conversation, then record Payment Not Confirmed if nothing was missed.",result:"cancelled"},
    {area:"authorization",title:"CUS-05 sent, STO-03 pending",what:"Authorization sequence was interrupted after customer message.",admin:"Resume the visible STO-03 task. Do not resend/roll back CUS-05 without evidence.",result:"State remains unchanged until STO-03"},
    {area:"delivery",title:"Pickup problem",what:"Not ready, package mismatch/damage, changed amount, transfer dispute or refusal.",admin:"Rider stops. Admin investigates and instructs; no false pickup is recorded.",result:"Normally ready_for_pickup or current state"},
    {area:"delivery",title:"Temporary delivery difficulty",what:"Customer does not answer, location is unclear, access is blocked or a short retry is practical.",admin:"Use judgment to wait, retry or reorganize. Record a material attempt.",result:"picked_up"},
    {area:"delivery",title:"Delivery cannot continue",what:"Admin decides the current trip has ended unsuccessfully.",admin:"Record failure evidence and known custody. Acknowledgement does not resolve it.",result:"delivery_failed"},
    {area:"delivery",title:"New redelivery trip",what:"A later physical trip is deliberately approved.",admin:"Confirm custody, condition, customer availability/location and any separately accepted fee.",result:"delivery_failed → picked_up"},
    {area:"delivery",title:"After-hours active order",what:"An authorized order reaches 22:00 while preparing or delivering.",admin:"Confirm all parties can continue, or coordinate next-day plan and physical custody.",result:"No clock-based state change"},
    {area:"cash",title:"Rider cash discrepancy",what:"Actual returned cash differs from expected cash.",admin:"Keep discrepancy visible and investigate facts; system does not assign liability.",result:"Order state unchanged"}
  ],
